import config
from pricing import calculate


def quote(lines):
    lines = list(lines)  # local copy; the caller's input is never mutated
    subtotal, tax = calculate(lines, config.TAX_PERCENT)

    if not lines:
        shipping = 0  # an empty order costs zero
    else:
        shipping = (0 if subtotal >= config.FREE_SHIPPING_CENTS
                    else config.SHIPPING_CENTS)

    return dict(subtotal_cents=subtotal, tax_cents=tax, shipping_cents=shipping,
                total_cents=subtotal + tax + shipping, brand=config.BRAND)

