def _round_half_up(amount, percent):
    """Exact integer round-half-up of amount * percent / 100."""
    return (amount * percent * 2 + 100) // 200


def calculate(lines, tax_percent):
    subtotal = sum(line['unit_cents'] * line['quantity'] for line in lines)
    return subtotal, _round_half_up(subtotal, tax_percent)

