def _round_half_up(numerator, denominator):
    quotient, remainder = divmod(numerator, denominator)
    if remainder * 2 >= denominator:
        quotient += 1
    return quotient


def calculate(lines, tax_percent):
    subtotal = 0
    for line in lines:
        subtotal += line['unit_cents'] * line['quantity']
    tax = _round_half_up(subtotal * tax_percent, 100)
    return subtotal, tax

